tml_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Single fused kernel for TripletMarginLoss (p=2, reduction='mean'):
//   loss_i = max(||a_i - p_i||_2 - ||a_i - n_i||_2 + margin, 0)
//   output = mean_i(loss_i)
// One warp handles one triplet (one row of length D). Per-lane partial
// sums are reduced with warp shuffles, accumulated per warp, and then
// reduced once per CTA through shared memory, so each block issues one
// atomicAdd instead of one per triplet. The kernel is DRAM-bandwidth bound
// (~97% DRAM utilization) and the input streams have zero temporal
// reuse, so all loads use the streaming/evict-first cache operator
// __ldcs (ld.global.cs). This keeps the three large input streams from
// thrashing L2/L1, shortens line residency, and raises the effective
// DRAM bandwidth available to the reduction.
template <int Threads>
__global__ void __launch_bounds__(Threads) triplet_margin_loss_kernel(
    const float* __restrict__ A,
    const float* __restrict__ P,
    const float* __restrict__ Nn,
    float* __restrict__ Out,
    int64_t B,
    int64_t D,
    float margin,
    float invB)
{
  constexpr int WarpsPerBlock = Threads / 32;
  const int lane = threadIdx.x & 31;
  const int64_t global_warp =
      (int64_t)blockIdx.x * WarpsPerBlock + (threadIdx.x >> 5);
  const int64_t num_warps = (int64_t)gridDim.x * WarpsPerBlock;
  const int64_t D4 = D / 4;
  // Grid-stride loop over triplets: one warp per triplet. Consecutive
  // lanes read consecutive float4 elements, so all loads are fully
  // coalesced 128-bit accesses.
  // Per-warp running sum of already-scaled triplet losses for the
  // hierarchical CTA reduction after the grid-stride loop.
  float warp_loss = 0.0f;
  for (int64_t b = global_warp; b < B; b += num_warps) {
    // Vectorized (float4) CuTe views of this warp's current row
    auto gA4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(A  + b * D)), make_shape(D4));
    auto gP4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(P  + b * D)), make_shape(D4));
    auto gN4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(Nn + b * D)), make_shape(D4));
    float acc_pos = 0.0f;
    float acc_neg = 0.0f;
    // Main vectorized sweep over the feature dimension with 4x unrolling:
    // each lane issues four independent streaming (__ldcs) 128-bit loads
    // per input stream per iteration, quadrupling memory-level parallelism
    // (more outstanding loads per warp) so the DRAM pipeline stays
    // saturated even for very deep rows. A 2x-unrolled loop handles the
    // remainder. Consecutive lanes still read consecutive float4s, so
    // every load remains a fully coalesced 128-bit access.
    const float4* a4 = reinterpret_cast<const float4*>(A  + b * D);
    const float4* p4 = reinterpret_cast<const float4*>(P  + b * D);
    const float4* n4 = reinterpret_cast<const float4*>(Nn + b * D);
    int64_t i = lane;
    for (; i + 96 < D4; i += 128) {
      float4 a0 = __ldcs(a4 + i);
      float4 a1 = __ldcs(a4 + i + 32);
      float4 a2 = __ldcs(a4 + i + 64);
      float4 a3 = __ldcs(a4 + i + 96);
      float4 p0 = __ldcs(p4 + i);
      float4 p1 = __ldcs(p4 + i + 32);
      float4 p2 = __ldcs(p4 + i + 64);
      float4 p3 = __ldcs(p4 + i + 96);
      float4 n0 = __ldcs(n4 + i);
      float4 n1 = __ldcs(n4 + i + 32);
      float4 n2 = __ldcs(n4 + i + 64);
      float4 n3 = __ldcs(n4 + i + 96);
      float dp0 = a0.x - p0.x;
      float dp1 = a0.y - p0.y;
      float dp2 = a0.z - p0.z;
      float dp3 = a0.w - p0.w;
      float dp4 = a1.x - p1.x;
      float dp5 = a1.y - p1.y;
      float dp6 = a1.z - p1.z;
      float dp7 = a1.w - p1.w;
      float dp8 = a2.x - p2.x;
      float dp9 = a2.y - p2.y;
      float dp10 = a2.z - p2.z;
      float dp11 = a2.w - p2.w;
      float dp12 = a3.x - p3.x;
      float dp13 = a3.y - p3.y;
      float dp14 = a3.z - p3.z;
      float dp15 = a3.w - p3.w;
      acc_pos += dp0 * dp0 + dp1 * dp1 + dp2 * dp2 + dp3 * dp3
               + dp4 * dp4 + dp5 * dp5 + dp6 * dp6 + dp7 * dp7
               + dp8 * dp8 + dp9 * dp9 + dp10 * dp10 + dp11 * dp11
               + dp12 * dp12 + dp13 * dp13 + dp14 * dp14 + dp15 * dp15;
      float dn0 = a0.x - n0.x;
      float dn1 = a0.y - n0.y;
      float dn2 = a0.z - n0.z;
      float dn3 = a0.w - n0.w;
      float dn4 = a1.x - n1.x;
      float dn5 = a1.y - n1.y;
      float dn6 = a1.z - n1.z;
      float dn7 = a1.w - n1.w;
      float dn8 = a2.x - n2.x;
      float dn9 = a2.y - n2.y;
      float dn10 = a2.z - n2.z;
      float dn11 = a2.w - n2.w;
      float dn12 = a3.x - n3.x;
      float dn13 = a3.y - n3.y;
      float dn14 = a3.z - n3.z;
      float dn15 = a3.w - n3.w;
      acc_neg += dn0 * dn0 + dn1 * dn1 + dn2 * dn2 + dn3 * dn3
               + dn4 * dn4 + dn5 * dn5 + dn6 * dn6 + dn7 * dn7
               + dn8 * dn8 + dn9 * dn9 + dn10 * dn10 + dn11 * dn11
               + dn12 * dn12 + dn13 * dn13 + dn14 * dn14 + dn15 * dn15;
    }
    for (; i + 32 < D4; i += 64) {
      float4 a0 = __ldcs(a4 + i);
      float4 a1 = __ldcs(a4 + i + 32);
      float4 p0 = __ldcs(p4 + i);
      float4 p1 = __ldcs(p4 + i + 32);
      float4 n0 = __ldcs(n4 + i);
      float4 n1 = __ldcs(n4 + i + 32);
      float dp0 = a0.x - p0.x;
      float dp1 = a0.y - p0.y;
      float dp2 = a0.z - p0.z;
      float dp3 = a0.w - p0.w;
      float dp4 = a1.x - p1.x;
      float dp5 = a1.y - p1.y;
      float dp6 = a1.z - p1.z;
      float dp7 = a1.w - p1.w;
      acc_pos += dp0 * dp0 + dp1 * dp1 + dp2 * dp2 + dp3 * dp3
               + dp4 * dp4 + dp5 * dp5 + dp6 * dp6 + dp7 * dp7;
      float dn0 = a0.x - n0.x;
      float dn1 = a0.y - n0.y;
      float dn2 = a0.z - n0.z;
      float dn3 = a0.w - n0.w;
      float dn4 = a1.x - n1.x;
      float dn5 = a1.y - n1.y;
      float dn6 = a1.z - n1.z;
      float dn7 = a1.w - n1.w;
      acc_neg += dn0 * dn0 + dn1 * dn1 + dn2 * dn2 + dn3 * dn3
               + dn4 * dn4 + dn5 * dn5 + dn6 * dn6 + dn7 * dn7;
    }
    for (; i < D4; i += 32) {
      float4 a = __ldcs(a4 + i);
      float4 p = __ldcs(p4 + i);
      float4 n = __ldcs(n4 + i);
      float dp0 = a.x - p.x;
      float dp1 = a.y - p.y;
      float dp2 = a.z - p.z;
      float dp3 = a.w - p.w;
      acc_pos += dp0 * dp0 + dp1 * dp1 + dp2 * dp2 + dp3 * dp3;
      float dn0 = a.x - n.x;
      float dn1 = a.y - n.y;
      float dn2 = a.z - n.z;
      float dn3 = a.w - n.w;
      acc_neg += dn0 * dn0 + dn1 * dn1 + dn2 * dn2 + dn3 * dn3;
    }
    // Scalar tail (handles D % 4 != 0)
    // Scalar tail (handles D % 4 != 0), also via streaming loads
    for (int64_t i = D4 * 4 + lane; i < D; i += 32) {
      float dp = __ldcs(A + b * D + i) - __ldcs(P + b * D + i);
      float dn = __ldcs(A + b * D + i) - __ldcs(Nn + b * D + i);
      acc_pos += dp * dp;
      acc_neg += dn * dn;
    }
    // Warp-level reduction via shuffles (all 32 lanes converge here)
    #pragma unroll
    for (int s = 16; s > 0; s >>= 1) {
      acc_pos += __shfl_down_sync(0xffffffffu, acc_pos, s);
      acc_neg += __shfl_down_sync(0xffffffffu, acc_neg, s);
    }
    if (lane == 0) {
      float d_pos = sqrtf(acc_pos);
      float d_neg = sqrtf(acc_neg);
      float loss  = fmaxf(d_pos - d_neg + margin, 0.0f);
      warp_loss += loss * invB;
    }
  }
  // Block-level reduction of per-triplet losses: one atomic per CTA
  // instead of one per triplet, reducing serialization on Out.
  __shared__ float block_losses[WarpsPerBlock];
  const int warp = threadIdx.x >> 5;
  if (lane == 0) {
    block_losses[warp] = warp_loss;
  }
  __syncthreads();
  if (warp == 0) {
    float block_loss = (lane < WarpsPerBlock) ? block_losses[lane] : 0.0f;
    #pragma unroll
    for (int s = 16; s > 0; s >>= 1) {
      block_loss += __shfl_down_sync(0xffffffffu, block_loss, s);
    }
    if (lane == 0) {
      atomicAdd(Out, block_loss);
    }
  }
}

torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor,
                                          torch::Tensor positive,
                                          torch::Tensor negative,
                                          double margin)
{
  TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(),
              "All inputs must be CUDA tensors");
  TORCH_CHECK(anchor.scalar_type() == at::kFloat &&
              positive.scalar_type() == at::kFloat &&
              negative.scalar_type() == at::kFloat,
              "All inputs must be float32");
  TORCH_CHECK(anchor.sizes() == positive.sizes() &&
              anchor.sizes() == negative.sizes(),
              "anchor, positive and negative must have the same shape");
  TORCH_CHECK(anchor.dim() >= 2, "Inputs must have at least 2 dimensions [B, ...]");

  auto a_c = anchor.contiguous();
  auto p_c = positive.contiguous();
  auto n_c = negative.contiguous();

  const int64_t B = (int64_t)a_c.size(0);
  const int64_t D = (int64_t)(a_c.numel() / a_c.size(0));

  auto out = torch::zeros({}, a_c.options());

  constexpr int Threads = 256;
  dim3 block(Threads);
  // Wave-quantized persistent grid sizing: query the maximum number of
  // CTAs that can be resident per SM for this kernel and size the grid
  // to exactly one full wave (num_sms * blocks_per_sm). The grid-stride
  // loop already covers arbitrary B, so this removes the partial-wave
  // tail effect (the previous fixed num_sms*8 grid oversubscribed the
  // device, leaving a ragged final wave) while keeping every SM busy
  // at the kernel's true achievable occupancy.
  static int num_sms = -1;
  static int blocks_per_sm = -1;
  if (num_sms < 0) {
    int dev = 0;
    cudaGetDevice(&dev);
    cudaDeviceGetAttribute(&num_sms, cudaDevAttrMultiProcessorCount, dev);
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &blocks_per_sm, triplet_margin_loss_kernel<Threads>, Threads, 0);
    if (blocks_per_sm < 1) blocks_per_sm = 1;
  }
  int64_t warps_per_block = Threads / 32;
  int64_t blocks_needed = (B + warps_per_block - 1) / warps_per_block;
  int64_t full_wave = (int64_t)num_sms * blocks_per_sm;
  int64_t grid_blocks = (blocks_needed < full_wave) ? blocks_needed : full_wave;
  dim3 grid((unsigned)grid_blocks);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  const float invB = 1.0f / (float)B;

  triplet_margin_loss_kernel<Threads><<<grid, block, 0, stream>>>(
      a_c.data_ptr<float>(),
      p_c.data_ptr<float>(),
      n_c.data_ptr<float>(),
      out.data_ptr<float>(),
      B, D,
      (float)margin,
      invB
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "triplet_margin_loss_kernel launch failed: ",
              cudaGetErrorString(err));

  return out;
}
"""

tml_ext = load_inline(
    name="cute_triplet_margin_loss_ext",
    cpp_sources=tml_cpp_decl,
    cuda_sources=tml_cuda_src,
    functions=["triplet_margin_loss_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Triplet Margin Loss (p=2, reduction='mean') implemented with a single
    fused CuTe/CUDA kernel: per-triplet distances, hinge, and mean reduction
    are all computed in one kernel launch.

    Parameters:
        margin (float): The margin between the positive and negative samples.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self._ext = tml_ext

    def forward(self, anchor, positive, negative):
        return self._ext.triplet_margin_loss_forward(
            anchor, positive, negative, self.margin
        )

